InfluxDB - TimescaleDB.ejemplo:
-- TimescaleDB: crear hypertable y consulta por ventanas de 5 minutos
SELECT create_hypertable('telemetria', 'tiempo');
SELECT time_bucket('5 minutes', tiempo) AS cubo, avg(cpu)
FROM telemetria
WHERE tiempo > now() - interval '6 hours'
GROUP BY cubo ORDER BY cubo DESC;

