-- Normalizado en 3FN:
CREATE TABLE codigos_postales (cp VARCHAR(10) PRIMARY KEY, ciudad VARCHAR(80) NOT NULL);
CREATE TABLE usuarios (id BIGINT PRIMARY KEY, nombre VARCHAR(80), cp VARCHAR(10) REFERENCES codigos_postales(cp));

PostGIS.ejemplo:
CREATE INDEX idx_tiendas_ubicacion ON tiendas USING GIST (ubicacion);
-- Buscar tiendas a menos de 2 km (usa índice GiST con ST_DWithin)
SELECT id, nombre
FROM tiendas
WHERE ST_DWithin(ubicacion, ST_SetSRID(ST_MakePoint(-99.1332, 19.4326), 4326)::geography, 2000);

