Reorganización y reconstrucción de índic.ejemplo:
-- PostgreSQL: actualizar estadísticas, limpiar sin bloqueo y reconstruir índice en vivo
VACUUM (ANALYZE, VERBOSE) pedidos;
REINDEX INDEX CONCURRENTLY idx_pedidos_estado;

-- MySQL InnoDB: desfragmentar tabla y estadísticas
