Replicación.ejemplo:
-- PostgreSQL: configurar replicación lógica selectiva
-- En el nodo publicador (líder):
CREATE PUBLICATION pub_analitica FOR TABLE pedidos, clientes;
-- En el nodo suscriptor (réplica analítica):
CREATE SUBSCRIPTION sub_analitica CONNECTION 'host=db-primary dbname=app' PUBLICATION pub_analitica;

