Sharding - Particionamiento.ejemplo:
-- Particionamiento declarativo por Hash en PostgreSQL (preludio o equivalente local al sharding)
CREATE TABLE eventos (
  tenant_id UUID NOT NULL,
  evento_id BIGINT NOT NULL,
  datos JSONB
) PARTITION BY HASH (tenant_id);
CREATE TABLE eventos_p0 PARTITION OF eventos FOR VALUES WITH (MODULUS 4, REMAINDER 0);
